import { transformStyleAttributes } from '../transformStyleAttributes';

describe('transformStyleAttributes', () => {
    it('replaces viewport heights on the root and nested elements', () => {
        const root = document.createElement('div');
        root.setAttribute('style', 'height: 100vh; color: red');
        root.innerHTML = '<section style="height: calc(50vh - 10px); width: 20px"><div style="height: 25vh !important"></div></section>';

        transformStyleAttributes(root);

        expect(root.style.height).toBe('auto');
        expect(root.style.color).toBe('red');

        const section = root.querySelector('section') as HTMLElement;
        expect(section.style.height).toBe('auto');
        expect(section.style.width).toBe('20px');

        const nested = root.querySelector('div') as HTMLElement;
        expect(nested.style.height).toBe('auto');
        expect(nested.style.getPropertyPriority('height')).toBe('important');
    });

    it('leaves other heights and styles unchanged', () => {
        const root = document.createElement('div');
        root.innerHTML = '<div style="height: 50px; min-height: 20vh"></div><div style="width: 10vh"></div>';
        const children = [...root.children] as HTMLElement[];
        const originalStyles = children.map((child) => child.getAttribute('style'));

        transformStyleAttributes(root);

        expect(children.map((child) => child.getAttribute('style'))).toEqual(originalStyles);
    });
});

